--
-- Table structure for table `showtime_seats`
--

DROP TABLE IF EXISTS `showtime_seats`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `showtime_seats` (
  `showtime_seat_id` bigint NOT NULL AUTO_INCREMENT,
  `showtime_id` bigint NOT NULL,
  `seat_id` bigint NOT NULL,
  `seat_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'AVAILABLE',
  `hold_token_hash` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `held_by_user_id` bigint DEFAULT NULL,
  `hold_session_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hold_expires_at` datetime DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`showtime_seat_id`),
  UNIQUE KEY `uk_showtime_seat` (`showtime_id`,`seat_id`),
  KEY `fk_showtime_seats_seat` (`seat_id`),
  KEY `fk_showtime_seats_user` (`held_by_user_id`),
  KEY `idx_showtime_seats_lookup` (`showtime_id`,`seat_status`,`hold_expires_at`),
  CONSTRAINT `fk_showtime_seats_seat` FOREIGN KEY (`seat_id`) REFERENCES `seats` (`seat_id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_showtime_seats_showtime` FOREIGN KEY (`showtime_id`) REFERENCES `showtimes` (`showtime_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_showtime_seats_user` FOREIGN KEY (`held_by_user_id`) REFERENCES `users` (`user_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1556 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

